impl Request {
    /// HTTP method and path of the request, using the most specific URL for the path parameters that are set.
    fn url(&self) -> (crate::http::Method, String) {
        (
            crate::http::Method::Post,
            format!(
                "/{}/_mvt/{}/{}/{}/{}",
                crate::typed::support::path_part(&self.index),
                crate::typed::support::path_part(&self.field),
                crate::typed::support::path_part(&self.zoom),
                crate::typed::support::path_part(&self.x),
                crate::typed::support::path_part(&self.y)
            ),
        )
    }

    /// HTTP method of the request.
    pub fn method(&self) -> crate::http::Method {
        self.url().0
    }

    /// Path of the request, with path parameters percent-encoded.
    pub fn path(&self) -> String {
        self.url().1
    }

    /// Query string parameters of the request.
    pub fn query(&self) -> Vec<(&'static str, String)> {
        let mut query = Vec::new();
        if let Some(value) = &self.error_trace {
            query.push(("error_trace", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.filter_path {
            query.push(("filter_path", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.human {
            query.push(("human", crate::typed::support::query_value(value)));
        }
        if let Some(value) = &self.pretty {
            query.push(("pretty", crate::typed::support::query_value(value)));
        }
        query
    }

    /// Body of the request.
    pub fn body(&self) -> RequestBody<'_> {
        RequestBody {
            aggs: self.aggs.as_ref(),
            buffer: self.buffer.as_ref(),
            exact_bounds: self.exact_bounds.as_ref(),
            extent: self.extent.as_ref(),
            fields: self.fields.as_ref(),
            grid_agg: self.grid_agg.as_ref(),
            grid_precision: self.grid_precision.as_ref(),
            grid_type: self.grid_type.as_ref(),
            query: self.query.as_ref(),
            runtime_mappings: self.runtime_mappings.as_ref(),
            size: self.size.as_ref(),
            sort: self.sort.as_ref(),
            track_total_hits: self.track_total_hits.as_ref(),
            with_labels: self.with_labels.as_ref(),
            project_routing: self.project_routing.as_ref(),
        }
    }

    pub(crate) async fn send(
        self,
        client: &crate::Elasticsearch,
    ) -> std::result::Result<Response, crate::Error> {
        use crate::http::{headers::HeaderMap, request::JsonBody};
        let (method, path) = self.url();
        let query = self.query();
        let response = client
            .transport()
            .send(
                method,
                &path,
                HeaderMap::new(),
                Some(&query),
                Some(JsonBody::new(self.body())),
                None,
            )
            .await?
            .error_for_status_code()?;
        response.json().await
    }
}

/// Body of a [`Request`], borrowing its values.
#[derive(Debug, serde::Serialize)]
pub struct RequestBody<'a> {
    #[serde(skip_serializing_if = "Option::is_none")]
    aggs: Option<
        &'a indexmap::IndexMap<String, crate::typed::_types::aggregations::AggregationContainer>,
    >,
    #[serde(skip_serializing_if = "Option::is_none")]
    buffer: Option<&'a i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    exact_bounds: Option<&'a bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    extent: Option<&'a i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    fields: Option<&'a crate::typed::_types::Fields>,
    #[serde(skip_serializing_if = "Option::is_none")]
    grid_agg: Option<&'a _types::GridAggregationType>,
    #[serde(skip_serializing_if = "Option::is_none")]
    grid_precision: Option<&'a i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    grid_type: Option<&'a _types::GridType>,
    #[serde(skip_serializing_if = "Option::is_none")]
    query: Option<&'a crate::typed::_types::query_dsl::QueryContainer>,
    #[serde(skip_serializing_if = "Option::is_none")]
    runtime_mappings: Option<&'a crate::typed::_types::mapping::RuntimeFields>,
    #[serde(skip_serializing_if = "Option::is_none")]
    size: Option<&'a i32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    sort: Option<&'a crate::typed::_types::Sort>,
    #[serde(skip_serializing_if = "Option::is_none")]
    track_total_hits: Option<&'a crate::typed::_global::search::_types::TrackHits>,
    #[serde(skip_serializing_if = "Option::is_none")]
    with_labels: Option<&'a bool>,
    #[serde(skip_serializing_if = "Option::is_none")]
    project_routing: Option<&'a crate::typed::_types::ProjectRouting>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
pub enum RequestFilterPath {
    String(String),
    StringList(Vec<String>),
}

impl From<String> for RequestFilterPath {
    fn from(value: String) -> Self {
        RequestFilterPath::String(value)
    }
}

impl From<Vec<String>> for RequestFilterPath {
    fn from(value: Vec<String>) -> Self {
        RequestFilterPath::StringList(value)
    }
}

impl From<&str> for RequestFilterPath {
    fn from(value: &str) -> Self {
        RequestFilterPath::String(value.into())
    }
}

